<div class="proma-accounting proma-accounting-sales">
  <header class="proma-accounting-page-header"><div><span class="proma-accounting-eyebrow">فروش و تخصیص</span><h2>فروش‌ها</h2><p>تغییر فروشنده با تاریخچه کامل ثبت و کمیسیون آینده از قانون فروشنده جدید محاسبه می‌شود.</p></div></header>
  <section class="proma-accounting-panel"><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>قرارداد</th><th>مشتری</th><th>فروشنده</th><th>مبلغ تأمین مالی‌شده</th><th>کانال</th><th>وضعیت</th><th>تخصیص فروشنده</th></tr></thead><tbody><?php foreach (($sales ?? []) as $sale): ?><tr><td><strong><?= e($sale['contract_number']) ?></strong></td><td><?= e($sale['customer_name']) ?></td><td><?= e($sale['seller_name'] ?: 'نیازمند تخصیص') ?></td><td><?= money_toman($sale['financed_amount']) ?></td><td><?= e($sale['sales_channel']) ?></td><td><span class="proma-accounting-status <?= ($sale['status'] ?? '') === 'active' ? 'is-active' : 'is-pending' ?>"><?= e($sale['status']) ?></span></td><td><form method="post" action="<?= e(url('plugin/accounting/sales/assign')) ?>" class="proma-accounting-inline-action"><?= csrf_field() ?><input type="hidden" name="sale_id" value="<?= (int) $sale['id'] ?>"><div class="proma-accounting-control"><select name="seller_user_id" required><option value="">انتخاب فروشنده</option><?php foreach (($staff ?? []) as $person): ?><option value="<?= (int) $person['id'] ?>"<?= (int) ($sale['seller_user_id'] ?? 0) === (int) $person['id'] ? ' selected' : '' ?>><?= e($person['full_name']) ?> (<?= e(role_label($person['role'])) ?>)</option><?php endforeach; ?></select></div><button class="btn btn-sm btn-primary" type="submit"><i data-feather="check"></i><span>ثبت</span></button></form></td></tr><?php endforeach; ?><?php if (empty($sales)): ?><tr><td colspan="7" class="empty">فروشی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div><?= render_pagination($pagination ?? [], static function ($page) { return url('plugin/accounting/sales', ['page' => $page]); }) ?></section>
</div>
